    return [[int(x!=1) for x in row[10:16]] for row in grid[:8]]"},{"nl":"Return the lower-right panel with its color 2 cells changed to 1 and zeros preserved.","code":"def transform(grid):
    return [[1 if x==2 else 0 for x in row[10:16]] for row in grid[12:20]]"},{"nl":"Return an 8×6 binary mask of locations where the upper-left and lower-left panels differ.","code":"def transform(grid):
    a=[row[:5] for row in grid[:8]]
    b=[row[:5] for row in grid[12:20]]
    return [[int(x!=y) for x,y in zip(ra,rb)]+[0] for ra,rb in zip(a,b)]"},{"nl":"Copy the upper-right panel, but replace its background color 1 by 0 and its holes by 1.","code":"def transform(grid):
